// Desktop 2.0 snapshot: src/main/charts.ts. Generated by scripts/import-pc-2.mjs; platform adaptations are explicit in that script.
// Чарты YouTube Music (версия 1.7): тот же публичный веб-API, что и поиск (browse FEmusic_charts с кодом страны).
// Без входа в аккаунт YouTube Music отдаёт (проверено 28.10.2026): «Top 100 Music Videos <страна>»,
// «Daily Top Music Videos», «Trending 20 <страна>» (у России и США, у «Мира» нет) и топ 40 артистов.
// Отдельного чарта песен («Top songs») без входа нет, поэтому «Топ песен» = Top 100 Music Videos.
// Кэш на сутки в папке данных: без сети показывается последний снимок.
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { getPlaylistSongs } from './artist/ytmArtist.js';
import { bestThumb, findAll, ytmCall, type ListItemRenderer, type Run } from './resolver/providers/innertube.js';
import type { Candidate, FetchFn } from './resolver/types.js';
import type { ChartCountry, ChartData } from '../shared/charts.js';

const DAY = 86_400_000;
const text = (runs?: Run[]) => (runs ?? []).map((r) => r.text).join('');

interface Shelf {
  header?: unknown;
  contents?: Record<string, unknown>[];
}

/** Плейлисты чартов и топ артистов со страницы чартов страны. */
export function parseChartsPage(data: unknown): { playlists: { title: string; id: string }[]; artists: ChartData['artists'] } {
  const playlists: { title: string; id: string }[] = [];
  const artists: ChartData['artists'] = [];
  for (const shelf of findAll<Shelf>(data, 'musicCarouselShelfRenderer')) {
    for (const c of shelf.contents ?? []) {
      const two = c.musicTwoRowItemRenderer as
        | { title?: { runs?: Run[] }; navigationEndpoint?: { browseEndpoint?: { browseId?: string } } }
        | undefined;
      const id = two?.navigationEndpoint?.browseEndpoint?.browseId;
      if (two && id?.startsWith('VL')) playlists.push({ title: text(two.title?.runs), id });
      const row = c.musicResponsiveListItemRenderer as (ListItemRenderer & { navigationEndpoint?: { browseEndpoint?: { browseId?: string } } }) | undefined;
      const ytId = row?.navigationEndpoint?.browseEndpoint?.browseId;
      if (row && ytId?.startsWith('UC')) {
        const cols = (row as unknown as { flexColumns?: { musicResponsiveListItemFlexColumnRenderer?: { text?: { runs?: Run[] } } }[] }).flexColumns ?? [];
        artists.push({
          name: text(cols[0]?.musicResponsiveListItemFlexColumnRenderer?.text?.runs),
          ytId,
          thumbnail: bestThumb(row.thumbnail?.musicThumbnailRenderer?.thumbnail),
          subtitle: text(cols[1]?.musicResponsiveListItemFlexColumnRenderer?.text?.runs).replace(/subscribers/i, 'подписчиков'),
        });
      }
    }
  }
  return { playlists, artists: artists.filter((a) => a.name) };
}

/**
 * Название клипа -> название песни: «Егор Крид - милый ублюдок (Премьера Клипа 2026)» -> «милый ублюдок».
 * Убираем имя артиста в начале и пометки клипа; пометки версии (Remix, feat.) оставляем.
 */
export function cleanVideoTitle(title: string, artist: string): string {
  let t = title.trim();
  const names = [artist, ...artist.split(/,\s*/)].map((a) => a.trim()).filter(Boolean);
  // «Артист - Песня» и «Артист — Песня» (бывает дважды: латиницей и кириллицей через «/»)
  for (const n of names) {
    const re = new RegExp(`^${n.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\s*[-–—]\\s*`, 'i');
    t = t.replace(re, '');
  }
  t = t.replace(/\s*[(\[|]\s*(official\s*(music\s*)?video|official\s*audio|music\s*video|lyric\s*video|video\s*klip[^)\]]*|клип[^)\]]*|премьера[^)\]]*|official\s*visualizer|visualizer|mv)\s*[)\]]?/gi, '');
  t = t.replace(/\s*\/\s*video\s*klip.*$/i, '').replace(/\s+\|\s*$/, '').trim();
  return t || title;
}

export class Charts {
  constructor(private o: { fetchFn: FetchFn; dir: string; log?: (m: string) => void }) {
    mkdirSync(o.dir, { recursive: true });
  }

  private file(cc: ChartCountry) {
    return path.join(this.o.dir, `${cc}.json`);
  }

  private snapshot(cc: ChartCountry): ChartData | null {
    try {
      return JSON.parse(readFileSync(this.file(cc), 'utf8')) as ChartData;
    } catch {
      return null;
    }
  }

  /** Чарт страны: свежий (не старше суток) из кэша, иначе из сети; без сети последний снимок. */
  async get(cc: ChartCountry, online: boolean): Promise<(ChartData & { stale: boolean }) | null> {
    const snap = this.snapshot(cc);
    if (snap && (Date.now() - snap.at < DAY || !online)) return { ...snap, stale: Date.now() - snap.at >= DAY };
    if (!online) return null;
    try {
      const fresh = await this.fetch(cc);
      writeFileSync(this.file(cc), JSON.stringify(fresh));
      return { ...fresh, stale: false };
    } catch (e) {
      this.o.log?.(`[charts] ${cc}: ${(e as Error).message}`);
      return snap ? { ...snap, stale: true } : null;
    }
  }

  private async fetch(cc: ChartCountry): Promise<ChartData> {
    const page = parseChartsPage(await ytmCall(this.o.fetchFn, 'browse', { browseId: 'FEmusic_charts', formData: { selectedValues: [cc] } }));
    const top = page.playlists.find((p) => /^Top 100 Music Videos/i.test(p.title)) ?? page.playlists.find((p) => /Daily Top Music Videos/i.test(p.title));
    const trend = page.playlists.find((p) => /^Trending/i.test(p.title));
    const [songs, trending] = await Promise.all([
      top ? getPlaylistSongs(this.o.fetchFn, top.id, 100) : Promise.resolve([] as Candidate[]),
      trend ? getPlaylistSongs(this.o.fetchFn, trend.id, 20) : Promise.resolve(null),
    ]);
    if (!songs.length && !page.artists.length) throw new Error('YouTube Music не отдал чарт');
    this.o.log?.(`[charts] ${cc}: песен ${songs.length}, в тренде ${trending?.length ?? 'нет'}, артистов ${page.artists.length}`);
    const clean = (list: Candidate[]) => list.map((c) => ({ ...c, title: cleanVideoTitle(c.title, c.artist) }));
    return { country: cc, at: Date.now(), songsTitle: top?.title ?? '', songs: clean(songs), trending: trending && clean(trending), trendingTitle: trend?.title ?? null, artists: page.artists };
  }
}
